def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return None

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, tgt):
        return [clamp_step(tgt[0] - src[0]), clamp_step(tgt[1] - src[1])]

    def step_away(src, tgt):
        return [clamp_step(src[0] - tgt[0]), clamp_step(src[1] - tgt[1])]

    env = observation.get("environment_name", "") or observation.get("env_name", "") or "resource_collection"
    self_pos = pos(observation.get("self_position")) or pos(observation.get("position")) or (0, 0)
    opp_pos = pos(observation.get("opponent_position")) or pos(observation.get("enemy_position")) or self_pos
    gw = observation.get("grid_width", 0) or observation.get("width", 0) or 0
    gh = observation.get("grid_height", 0) or observation.get("height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", observation.get("role", "pursuer"))
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = []
        if gw > 0 and gh > 0:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        else:
            corners = [(-5, -5), (-5, 5), (5, -5), (5, 5)]
        target = max(corners, key=lambda c: dist(c, opp_pos))
        return step_toward(self_pos, target)

    if env == "territory_control":
        candidates = []
        for key in ("unclaimed_cells", "opponent_territory", "neutral_cells", "frontier_cells", "targets"):
            items = observation.get(key) or []
            for item in items:
                p = pos(item)
                if p is not None:
                    candidates.append(p)
        if candidates:
            target = min(candidates, key=lambda c: dist(c, self_pos))
            return step_toward(self_pos, target)
        return step_away(self_pos, opp_pos)

    resources = []
    for key in ("resources", "resource_positions", "resource_cells", "targets"):
        items = observation.get(key) or []
        for item in items:
            p = pos(item)
            if p is not None:
                resources.append(p)

    if resources:
        target = min(resources, key=lambda c: dist(c, self_pos))
        return step_toward(self_pos, target)

    if gw > 0 and gh > 0:
        center = (gw // 2, gh // 2)
        return step_toward(self_pos, center)

    return step_away(self_pos, opp_pos)

